package apispec

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strings"

	"gopkg.in/yaml.v3"

	"github.com/bestagentkits/sisf/pkg/core"
)

// PathPrefix is where the REST surface serves each action: POST
// PathPrefix + name.
const PathPrefix = "/api/v1/actions/"

// header marks the generated files so nobody edits them by hand.
const header = "Generated by go generate ./internal/actions/... from the action registry. Do not edit."

// idempotencyKeyDescription describes the idempotency key of a write.
const idempotencyKeyDescription = "A retry with the same key and input within 24 hours gets the first answer without the write running again; the same key with another input is CONFLICT."

// OpenAPI renders the OpenAPI 3.1 document of specs. The output is stable:
// the same specs always give the same bytes.
func OpenAPI(specs []core.ActionSpec) ([]byte, error) {
	paths := map[string]any{}
	for _, spec := range specs {
		op, err := operation(spec)
		if err != nil {
			return nil, err
		}
		paths[PathPrefix+spec.Name] = map[string]any{"post": op}
	}
	doc := map[string]any{
		"openapi": "3.1.0",
		"info": map[string]any{
			"title":   "SISF action API",
			"version": "v1",
			"description": "Every surface of the factory calls this one action service. An action's description " +
				"documents it and never grants permission. Sensitive writes go plan, approval, execute, audit.",
		},
		"paths":      paths,
		"components": components(),
	}
	var buf bytes.Buffer
	buf.WriteString("# " + header + "\n")
	enc := yaml.NewEncoder(&buf)
	enc.SetIndent(2)
	if err := enc.Encode(doc); err != nil {
		return nil, fmt.Errorf("encode the OpenAPI document: %w", err)
	}
	if err := enc.Close(); err != nil {
		return nil, fmt.Errorf("encode the OpenAPI document: %w", err)
	}
	return buf.Bytes(), nil
}

// operation describes one action as a POST operation.
func operation(spec core.ActionSpec) (map[string]any, error) {
	input, err := schemaOf(spec.Input)
	if err != nil {
		return nil, fmt.Errorf("action %s input schema: %w", spec.Name, err)
	}
	output, err := schemaOf(spec.Output)
	if err != nil {
		return nil, fmt.Errorf("action %s output schema: %w", spec.Name, err)
	}
	body := map[string]any{"input": input}
	result := map[string]any{"output": output}
	if spec.Mutates() {
		body["dry_run"] = map[string]any{"type": "boolean", "description": "Report exactly what would change and change nothing."}
		body["idempotency_key"] = map[string]any{"type": "string", "maxLength": 256, "description": idempotencyKeyDescription}
		result["plan"] = ref("DryRun")
		result["audit_id"] = map[string]any{"type": "string"}
	}
	if spec.Sensitivity.NeedsApproval() {
		body["approval_id"] = map[string]any{"type": "string",
			"description": "The approved request this call spends. Without it, the call files a request and answers APPROVAL_REQUIRED."}
	}
	roles := make([]string, len(spec.Roles))
	for i, r := range spec.Roles {
		roles[i] = string(r)
	}
	area, _, _ := strings.Cut(spec.Name, ".")
	return map[string]any{
		"operationId": strings.ReplaceAll(spec.Name, ".", "_"),
		"summary":     spec.Summary,
		"tags":        []string{area},
		"security":    []map[string][]string{{"bearerAuth": spec.Scopes}},
		"requestBody": map[string]any{"required": false, "content": jsonContent(map[string]any{
			"type": "object", "additionalProperties": false, "properties": body})},
		"responses": map[string]any{
			"200":     map[string]any{"description": "The action ran.", "content": jsonContent(map[string]any{"type": "object", "properties": result})},
			"default": map[string]any{"$ref": "#/components/responses/Error"},
		},
		"x-sisf-action":      spec.Name,
		"x-sisf-sensitivity": string(spec.Sensitivity),
		"x-sisf-roles":       roles,
		"x-sisf-step-up":     spec.StepUp,
		"x-sisf-dry-run":     spec.Mutates(),
	}, nil
}

// schemaOf decodes a JSON Schema document; an absent one is any object.
func schemaOf(raw json.RawMessage) (any, error) {
	if len(raw) == 0 {
		return map[string]any{"type": "object"}, nil
	}
	var doc any
	if err := json.Unmarshal(raw, &doc); err != nil {
		return nil, err
	}
	return doc, nil
}

func ref(name string) map[string]any { return map[string]any{"$ref": "#/components/schemas/" + name} }

func jsonContent(schema any) map[string]any {
	return map[string]any{"application/json": map[string]any{"schema": schema}}
}

// components holds the shared error and dry-run shapes.
func components() map[string]any {
	codes := make([]string, 0, len(core.ErrorCodes()))
	for _, c := range core.ErrorCodes() {
		codes = append(codes, string(c))
	}
	str := map[string]any{"type": "string"}
	return map[string]any{
		"securitySchemes": map[string]any{"bearerAuth": map[string]any{"type": "http", "scheme": "bearer",
			"description": "A session, personal access token or service token; its scopes must cover the action's."}},
		"responses": map[string]any{"Error": map[string]any{"description": "A typed error with the next valid steps.",
			"content": jsonContent(map[string]any{"type": "object", "required": []string{"error"},
				"properties": map[string]any{"error": ref("Error")}})}},
		"schemas": map[string]any{
			"ErrorCode": map[string]any{"type": "string", "enum": codes},
			"NextAction": map[string]any{"type": "object", "required": []string{"action"}, "properties": map[string]any{
				"action": str, "description": str, "params": map[string]any{"type": "object", "additionalProperties": str}}},
			"Error": map[string]any{"type": "object", "required": []string{"code", "message"}, "properties": map[string]any{
				"code": ref("ErrorCode"), "message": str,
				"next_actions": map[string]any{"type": "array", "items": ref("NextAction")},
				"details":      map[string]any{"type": "object", "additionalProperties": str}}},
			"Change": map[string]any{"type": "object", "required": []string{"resource", "op"}, "properties": map[string]any{
				"resource": str, "op": map[string]any{"type": "string", "enum": []string{"create", "update", "delete"}},
				"before": map[string]any{}, "after": map[string]any{}}},
			"DryRun": map[string]any{"type": "object", "required": []string{"changes", "requires_approval"}, "properties": map[string]any{
				"changes": map[string]any{"type": "array", "items": ref("Change")}, "requires_approval": map[string]any{"type": "boolean"},
				"warnings": map[string]any{"type": "array", "items": str}}},
		},
	}
}
